    },
    {
      "id": "reporting-40-or-60",
      "handled": "asked",
      "evidence": "Reporting time fell by **40% in your resume versus 60% in LinkedIn**—which is correct, how was it measured, and whose result was it?"
    },
    {
      "id": "fraudshield-not-real-time",
      "handled": "asked",
      "evidence": "For **FraudShield, AutoPilot and Lisbon Rent Map**, briefly explain what each actually does, whether it was a course project, prototype or live product"
    },
    {
      "id": "autopilot-is-a-script",
      "handled": "asked",
      "evidence": "For **FraudShield, AutoPilot and Lisbon Rent Map**, briefly explain what each actually does, whether it was a course project, prototype or live product"
    },
    {
      "id": "efficiency-35-unmeasured",
      "handled": "asked",
      "evidence": "For “200+ staff” and “35% efficiency improvement,” what was measured, over what period, and was it measured or estimated?"
    },
    {
      "id": "bank-confidential",
      "handled": "asked",
      "evidence": "do you have permission to show employer work or client stories?"
    },
    {
      "id": "rent-map-3000-or-5000",
      "handled": "asked",
      "evidence": "For Rent Map, which is correct—**3,000 or 5,000 monthly visitors**—and what does that count measure, from when?"
    },
    {
      "id": "msc-dates",
      "handled": "asked",
      "evidence": "Did your MSc end in **2021 or 2022**?"
    },
    {
      "id": "hackathon-was-a-team",
      "handled": "asked",
      "evidence": "Was it a team award, and what was your part?"
    },
    {
      "id": "founder-title",
      "handled": "asked",
      "evidence": "Is “Founder & Product Analyst” still how you describe yourself? What was DataTugas, what did you personally do, who else was involved"
    }
  ],
  "final_asserts": [],
  "invented": [],
  "concepts_offered": 3,
  "concepts_differ_in_kind": true,
  "final": {
    "question": "How do you make a dashboard people actually use?",
    "is_question": true,
    "form": "Rafael's analysis memo: question, data, what I did, what I found, what I would do, with context and appendix added.",
    "object": "A packet of seven thin 3D memo pages that separates, rearranges and reassembles throughout the scroll.",
    "object_in_pieces": true
  },
  "tests": {
    "swap": {
      "result": "pass",
      "reason": "The narrative uses Rafael's explicitly named memo sequence, his live Rent Map and his specific sample-tracking and weekly-report work as its foundation."
    },
    "backdrop": {
      "result": "fail",
      "reason": "The pages mainly arrange labels and evidence already explained in HTML, so removing their 3D treatment loses presentation rather than a substantive explanation."
    },
    "depth": {
      "result": "pass",
      "reason": "The opening question leads through evidence, personal contribution and results to a proposed answer and hiring contact."
    },
    "clipart": {
      "result": "pass",
      "reason": "The memo packet is a working document Rafael actually uses, rather than a stock emblem of an analyst."
    },
    "honesty": {
      "result": "pass",
      "reason": "The final plan incorporates the corrections, qualifies approximate results and excludes unsupported claims and confidential artifacts."
    },
    "thirty_seconds": {
      "result": "pass",
      "reason": "The opening supplies Rafael's name, product analyst positioning, the five-to-two-hour result and an immediately reachable contact action."
    },
    "plain_reader": {
      "result": "pass",
      "reason": "The opening uses understandable language about useful dashboards and a concrete reporting-time result without inflated technical claims."
    }
  },
  "copied_example": false,
  "covers": {
    "phone": true,
    "reduced_motion": true,
    "no_3d": true,
    "other_needs": true,
    "look_and_type": true
  },
  "decided_list": true,
  "overstatement": "not_asked",
  "summary": "The plan turns Rafael's analysis memo into a seven-part portfolio with carefully bounded evidence, clear interactions and complete fallback provisions. Its greatest weakness is that the moving 3D pages mostly illustrate an already readable document rather than reveal something that needs spatial explanation."
}
